DELETE FROM "airtable"."event_attendance" as d WHERE EXISTS (SELECT 1 FROM "airtable_staging"."event_attendance" as s WHERE d."id" = s."id")
INSERT INTO "airtable"."event_attendance"("id", "created_time", "fields__date", "fields__name", "fields__email", "fields__event_id", "fields__attendance_id", "_dlt_load_id", "_dlt_id")                  SELECT "id", "created_time", "fields__date", "fields__name", "fields__email", "fields__event_id", "fields__attendance_id", "_dlt_load_id", "_dlt_id"                     FROM (                         SELECT ROW_NUMBER() OVER (partition BY "id" ORDER BY (SELECT NULL)) AS _dlt_dedup_rn, "id", "created_time", "fields__date", "fields__name", "fields__email", "fields__event_id", "fields__attendance_id", "_dlt_load_id", "_dlt_id"                         FROM "airtable_staging"."event_attendance"                     ) AS _dlt_dedup_numbered WHERE _dlt_dedup_rn = 1 AND (1 = 1)          